// ==========================================
// ⚙️ LUNAS WIRKUNG: WUNDEN LECKEN (Kombiniert)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    let fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (!fwMacro) fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.Ty8bzv98qwkGH9Qn");
    if (fwMacro) await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150)); 

    const DSK_FW = globalThis.DSK || DSK; 
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Wunden lecken";
    const ahne = "nurti";
    const finalEffektName = `${gabenName} (Nurti)`;
    const aepKosten = 8;
    const iconBild = DSK_FW.Symbol(ahne);

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. CASTER ERMITTELN ---
    let wirkenderActor = null;
    if (typeof actor !== "undefined" && actor) {
        wirkenderActor = actor; 
    } else if (typeof testData !== "undefined" && testData && testData.speaker) {
        wirkenderActor = game.actors.get(testData.speaker.actor);
    }
    if (!wirkenderActor) wirkenderActor = canvas.tokens.controlled[0]?.actor;
    if (!wirkenderActor) wirkenderActor = game.user.character;

    if (!wirkenderActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(wirkenderActor).forEach(id => ownerIds.add(id));

    // --- 3. TARGET PRÜFUNG (MUSS VOR ABZUG PASSIEREN) ---
    const targets = Array.from(game.user.targets);
    if (targets.length === 0) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst jemanden per Target aus, den du putzen möchtest!");
    }

    // --- 4. AEP PRÜFUNG ---
    const currentAeP = foundry.utils.getProperty(wirkenderActor, "system.stats.AeP.value") || 0;

    if (currentAeP < aepKosten) {
        await wirkenderActor.update({ "system.stats.AeP.value": 0 });
        const failHtml = `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                <div class="dskbox2" style="margin-top:10px; text-align:center;">
                    <p style="margin-bottom: 8px;"><b>${wirkenderActor.name}</b> hat versucht, die Gabe zu wirken.</p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px; color: #8b0000;"><b>Fehlschlag!</b> Die Kraft reicht nicht aus.</p>
                    <p style="margin-bottom: 8px;">Die restlichen <b>${currentAeP} AeP</b> wurden verbraucht, aber die Gabe schlägt fehl.</p>
                </div>
            </div>
        `;
        return ChatMessage.create({ speaker: { alias: "System" }, content: failHtml, whisper: Array.from(ownerIds).filter(id => game.users.get(id)) });
    }

    // --- 5. BERECHNUNGEN FÜR DIALOG ---
    let qs = 1;
    if (typeof testData !== "undefined") {
        qs = Number(testData?.result?.QL || testData?.qualityStep || 1);
    }
    const maxMinuten = qs * 4;

    // --- 6. DIALOG AUFRUFEN ---
    const dialogContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top: 10px; color: #000;">
                <p style="margin-bottom: 10px;"><b>Wie lange möchtest du das Ziel putzen?</b></p>
                <p style="font-size: 0.9em; margin-bottom: 10px; color: #555;">(Pro Minute wird 1 LeP geheilt. Deine QS erlaubt maximal <b>${maxMinuten}</b> Minuten.)</p>
                <div style="display: flex; align-items: center; justify-content: center; gap: 10px; margin-bottom: 5px;">
                    <label style="font-weight: bold;">Minuten:</label>
                    <input type="number" id="putzMinuten" value="${maxMinuten}" min="1" max="${maxMinuten}" style="width: 60px; text-align: center; border: 1px solid #76301b; border-radius: 3px;">
                </div>
            </div>
        </div>
    `;

    new Dialog({
        title: `Wunden lecken (Max: ${maxMinuten} Min)`,
        content: dialogContent,
        buttons: {
            confirm: {
                icon: '<i class="fas fa-heart"></i>',
                label: "Putzen & Heilen",
                callback: async (html) => {
                    const container = html instanceof jQuery ? html[0] : html;
                    let minutenEingabe = Number(container.querySelector("#putzMinuten").value) || 0;

                    if (minutenEingabe <= 0) {
                        ui.notifications.warn("Luna sagt 🌙: Du musst schon mindestens eine Minute putzen!");
                        return;
                    }
                    if (minutenEingabe > maxMinuten) minutenEingabe = maxMinuten;

                    // AEP ABZIEHEN
                    await wirkenderActor.update({ "system.stats.AeP.value": currentAeP - aepKosten });

                    // ZIELE HEILEN
                    const erfolge = [];
                    const fehler = [];

                    for (let t of targets) {
                        if (!t.actor) continue;

                        let istLebewesen = DSK_FW.Effekt.CheckTarget(t.actor, "lebewesen") ||
                                           DSK_FW.Effekt.CheckTarget(t.actor, "erwachte") ||
                                           t.actor.type === "character" ||
                                           t.actor.type === "npc";

                        if (DSK_FW.Effekt.CheckTarget(t.actor, "geist") || DSK_FW.Effekt.CheckTarget(t.actor, "untot")) {
                            istLebewesen = false;
                        }

                        if (!istLebewesen) {
                            fehler.push({ name: t.name, grund: "Kein Lebewesen" });
                            continue;
                        }

                        const maxLeP = t.actor.system.stats.LeP.max;
                        const currentLeP = t.actor.system.stats.LeP.value;

                        if (currentLeP >= maxLeP) {
                            fehler.push({ name: t.name, grund: "Bereits volle LeP" });
                            continue;
                        }

                        let healAmount = minutenEingabe;
                        let neueLeP = currentLeP + healAmount;
                        if (neueLeP > maxLeP) {
                            healAmount = maxLeP - currentLeP;
                            neueLeP = maxLeP;
                        }

                        await t.actor.update({"system.stats.LeP.value": neueLeP});
                        erfolge.push({ name: t.name, amount: healAmount, total: neueLeP, max: maxLeP });
                    }

                    // CHAT-KARTE BAUEN
                    targets.forEach(t => {
                        if(t?.actor) Object.entries(t.actor.ownership || {}).filter(([id, lvl]) => lvl === 3).forEach(([id]) => ownerIds.add(id));
                    });

                    const erfolgHtml = erfolge.length > 0 
                        ? `<div style="margin-top: 10px; margin-bottom: 10px;">
                               <p style="margin-bottom: 5px;"><span style="color:#18940F; font-weight:bold;">Erfolgreich geputzt:</span></p>
                               <ul class="dsklist" style="margin-top:0; font-weight:normal; color: #000;">
                                   ${erfolge.map(e => `<li><b>${e.name}</b> <span style="color: #2e7d32;">(+${e.amount} LeP)</span> ➔ ${e.total}/${e.max}</li>`).join("")}
                               </ul>
                           </div>` : ``;

                    const fehlschlagHtml = fehler.length > 0
                        ? `<div style="margin-top: 10px; margin-bottom: 10px;">
                               <p style="margin-bottom: 5px;"><span style="color:#B30000; font-weight:bold;">Fehlschlag:</span></p>
                               <ul class="dsklist" style="margin-top:0; font-weight:normal; color: #000;">
                                   ${fehler.map(f => `<li>${f.name} (${f.grund})</li>`).join("")}
                               </ul>
                           </div>` : ``;

                    const resultHtml = `
                        <div style="font-family: 'Signika', sans-serif;">
                            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                            <div class="dskbox2" style="margin-top:10px;">
                                <p style="margin-bottom: 8px;"><b>${wirkenderActor.name}</b> wendet Zeit und Fürsorge auf, um Wunden zu lecken.</p>
                                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                                <p style="margin-bottom: 8px; color: #76301b;"><b>Kosten:</b> Die AeP in Höhe von <b>${aepKosten}</b> sind abgezogen worden.</p>
                                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                                <p style="margin-top:0; margin-bottom:8px; text-align: justify;">Das Nurtikind pflegt ausdauernd die Wunden. Jeder Minute des Putzens schließt tiefe Schnitte und lindert den Schmerz.</p>
                                ${erfolgHtml}
                                ${fehlschlagHtml}
                                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                                <p style="text-align:center; font-weight:bold; margin-bottom: 0;">
                                    Dauer des Putzens:<br>${minutenEingabe} Minuten
                                </p>
                            </div>
                        </div>
                    `;

                    await ChatMessage.create({
                        speaker: { alias: "System" },
                        whisper: Array.from(ownerIds).filter(id => game.users.get(id)),
                        content: resultHtml
                    });
                }
            },
            cancel: {
                icon: '<i class="fas fa-times"></i>',
                label: "Abbrechen"
            }
        },
        default: "confirm",
        render: (html) => {
            const container = html instanceof jQuery ? html[0] : html;
            const btns = container.querySelectorAll('.dialog-button');
            btns.forEach(btn => {
                btn.style.background = 'linear-gradient(#76301b,#582617)';
                btn.style.color = '#f8f6f5';
                btn.style.border = '1px solid #000';
                btn.style.fontWeight = 'bold';
            });
        }
    }).render(true);
})();
